"""Registrar leituras e inspeção visual do lote B5-02 (registro 129)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==16
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,17)),same
notes={1:'Abertura, quadro das formas de aquisição e ficha antes da tentativa.',2:'Lista de ritual, Doma e criação; começo do quadro de projeto.',3:'Fim do quadro, teste de criação e ajuda.',4:'Evolução, reconstrução, transferência e acompanhar entre cenas.',5:'Invocador que deixa de agir; abertura do Tempo e materiais com a tabela.',6:'Horas, etapas e quadro de materiais; falha.',7:'Detalhar, ajuda e exemplo do Vigia.',8:'Quadro dos ciclos; abertura de Reconstruir e quadro das passagens.',9:'Teste, exemplo de reconstrução e mais de uma Classe.',10:'Transferência com quadro e exemplo.',11:'Herança e registro; abertura da prova do Cão de sombra.',12:'Quadro das condições da prova e o espaço.',13:'Ficha do cão em quadros; Mordida, Mordida precisa e Farejador.',14:'Turno do adversário e ataques de Kaito com Canalizar corrigido; ajuda e desistência.',15:'Socorro, quadro do resultado e registro.',16:'Fim do registro e como preparar outra prova; meia página final.'}
save('revisao-final.json',{'registro':129,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das quatro fontes e das regras citadas, quatro cópias, remissões, clareza e a correção de Canalizar na prova do Cão de sombra.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; nenhuma alteração necessária.'}],'ajuste_de_diagramacao':'Sem ajuste necessário; rótulos presos aos títulos.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if False else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','A última página tem meia coluna de texto; reavaliar o fechamento na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s043':[1,5],'s045':[5,8],'s046':[8,11],'s051':[11,16]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':129,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':129,'lote':'B5-02','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':55,'casos_pendentes':4,'lotes_pendentes':1,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'B5-03','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':4},ensure_ascii=False))
